import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    """
    Run a non-blocking echo server for ``run_duration`` seconds.

    Every chunk of data received from a client is appended with the server's
    current time (as an ISO formatted string) and sent back to that client.
    All sockets are handled in a non-blocking way using ``select``; per-socket
    exceptional conditions (disconnects, errors, full send buffers) are handled
    individually so that one misbehaving client cannot stop the server.

    Returns:
        str: A status message describing the server's operation and how long
        it ran.
    """
    start_time = datetime.now()
    deadline = start_time + timedelta(seconds=run_duration)

    # Map of socket -> outgoing byte buffer (queue) for that connection.
    message_queues = {}
    server_socket = None
    inputs = []
    outputs = []

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.setblocking(False)
        server_socket.bind((server_address, server_port))
        server_socket.listen(5)
        inputs = [server_socket]

        while datetime.now() < deadline:
            remaining = (deadline - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            try:
                readable, writable, exceptional = select.select(
                    inputs, outputs, inputs, min(remaining, 0.5)
                )
            except (OSError, ValueError):
                # select interrupted or given an invalid descriptor; retry.
                continue

            # --- Handle readable sockets -------------------------------------
            for sock in readable:
                if sock is server_socket:
                    # Accept every pending connection.
                    while True:
                        try:
                            connection, _ = server_socket.accept()
                        except (BlockingIOError, InterruptedError):
                            break
                        except OSError:
                            break
                        connection.setblocking(False)
                        inputs.append(connection)
                        message_queues[connection] = queue.Queue()
                else:
                    try:
                        data = sock.recv(buffer_size)
                    except (BlockingIOError, InterruptedError):
                        continue
                    except OSError:
                        data = b""

                    if data:
                        timestamp = datetime.now().isoformat()
                        if isinstance(data, bytes):
                            payload = data + timestamp.encode("utf-8")
                        else:
                            payload = data + timestamp
                        message_queues[sock].put(payload)
                        if sock not in outputs:
                            outputs.append(sock)
                    else:
                        # Client closed the connection.
                        if sock in outputs:
                            outputs.remove(sock)
                        if sock in inputs:
                            inputs.remove(sock)
                        message_queues.pop(sock, None)
                        try:
                            sock.close()
                        except OSError:
                            pass

            # --- Handle writable sockets -------------------------------------
            for sock in writable:
                try:
                    next_msg = message_queues[sock].get_nowait()
                except (KeyError, queue.Empty):
                    # Nothing left to send for this socket.
                    if sock in outputs:
                        outputs.remove(sock)
                    continue

                try:
                    sock.send(next_msg)
                except (BlockingIOError, InterruptedError):
                    # Could not send now; keep the message for later.
                    message_queues[sock].put(next_msg)
                except OSError:
                    # Broken connection: drop it entirely.
                    if sock in outputs:
                        outputs.remove(sock)
                    if sock in inputs:
                        inputs.remove(sock)
                    message_queues.pop(sock, None)
                    try:
                        sock.close()
                    except OSError:
                        pass

            # --- Handle exceptional conditions -------------------------------
            for sock in exceptional:
                if sock in inputs:
                    inputs.remove(sock)
                if sock in outputs:
                    outputs.remove(sock)
                message_queues.pop(sock, None)
                if sock is not server_socket:
                    try:
                        sock.close()
                    except OSError:
                        pass

    finally:
        # Clean up every remaining connection and the listening socket.
        for sock in list(message_queues.keys()):
            try:
                sock.close()
            except OSError:
                pass
        message_queues.clear()
        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return (
        "Server ran for {:.2f} seconds, echoing data with timestamps "
        "on {}:{}".format(elapsed, server_address, server_port)
    )

import pandas as pd
import numpy as np
import itertools
def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    n_positions = max(len(t) for t in data_list)
    means = []
    for i in range(n_positions):
        values = []
        for t in data_list:
            if i < len(t):
                v = t[i]
                if isinstance(v, (int, float, np.integer, np.floating)) and not isinstance(v, bool):
                    values.append(v)
        means.append(np.mean(values) if values else np.nan)

    return pd.DataFrame({'Mean Value': means},
                        index=['Position {}'.format(i) for i in range(n_positions)])
